// The ranked list is the whole point of this sim: the winner changes with the
// stated priority, so the ranking is recomputed rather than fixed.
const VENDOR_REASONS = {
    'Cost Fit':        {'Vendor A': 'free tier covers a small club', 'Vendor B': 'moderate monthly cost', 'Vendor C': 'priced for organisations, not clubs'},
    'Data Privacy':    {'Vendor A': 'trains on submitted data by default', 'Vendor B': 'contractual no-training guarantee', 'Vendor C': 'no-training on paid tiers only'},
    'Output Quality':  {'Vendor A': 'good drafts, occasional tone drift', 'Vendor B': 'serviceable but generic', 'Vendor C': 'consistently strong drafts'},
    'Language Support':{'Vendor A': 'strong in English only', 'Vendor B': 'broad multilingual coverage', 'Vendor C': 'limited beyond English'}
};

function renderRanking(criterion) {
    const idx = chartData.labels.indexOf(criterion);
    const rows = chartData.datasets
        .map((d, i) => ({ name: d.label, score: d.data[idx], visible: chart.isDatasetVisible(i) }))
        .filter(r => r.visible)
        .sort((a, b) => b.score - a.score);
    const box = document.getElementById('ranking');
    if (!box) return;
    box.innerHTML = '<strong>Ranked on ' + criterion + '</strong><ol>' +
        rows.map(r => '<li>' + r.name + ' - ' + r.score + '/5 <em>(' +
                 (VENDOR_REASONS[criterion][r.name] || '') + ')</em></li>').join('') +
        '</ol>';
}

function onControl(id, value) {
    if (id === 'priority') renderRanking(value);
}

// keep the ranking in step with the vendor checkboxes too
document.querySelectorAll('[data-dataset]').forEach(el =>
    el.addEventListener('change', () => {
        const sel = document.querySelector('select[data-control="priority"]');
        renderRanking(sel ? sel.value : chartData.labels[0]);
    }));

renderRanking(chartData.labels[0]);
